//! Expo's API, as the reference's `ExpoApi.ts` calls it: the credential (a
//! token saved for the host, then `EXPO_TOKEN`, then the `eas login`
//! session), and its GraphQL operations, whose documents are the reference's
//! (`expo_documents.json`, generated by `scripts/update_agent_tools.py`).
use serde_json::{json, Value};
use std::{sync::LazyLock, time::Duration};

const EXPO_GRAPHQL_URL: &str = "https://api.expo.dev/graphql";
const REQUEST_TIMEOUT: Duration = Duration::from_secs(30);

static DOCUMENTS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(include_str!("expo_documents.json")).expect("Expo GraphQL documents")
});

/// An extra trusted root for tests, read from `T3CODE_TEST_EXTRA_CA_FILE`, in
/// debug builds only. The parity suites (which run debug builds) put a
/// loopback stand-in for Expo's fixed HTTPS API behind a certificate from a
/// test CA; release builds never read the variable and trust only the
/// built-in roots.
#[cfg(debug_assertions)]
fn test_root_certificates() -> Vec<reqwest::Certificate> {
    let Some(path) = std::env::var_os("T3CODE_TEST_EXTRA_CA_FILE") else {
        return Vec::new();
    };
    std::fs::read(path)
        .ok()
        .and_then(|pem| reqwest::Certificate::from_pem_bundle(&pem).ok())
        .unwrap_or_default()
}

#[cfg(not(debug_assertions))]
fn test_root_certificates() -> Vec<reqwest::Certificate> {
    Vec::new()
}

/// The HTTP client for Expo's API (and its sessions' hosts).
pub(super) fn client() -> reqwest::Client {
    let mut builder = reqwest::Client::builder().redirect(reqwest::redirect::Policy::none());
    for certificate in test_root_certificates() {
        builder = builder.add_root_certificate(certificate);
    }
    builder.build().unwrap()
}

/// `ExpoCredential`: where it came from, and the header it is sent as.
#[derive(Clone, Debug)]
pub(super) struct Credential {
    pub source: &'static str,
    pub header: &'static str,
    pub value: String,
}

/// `ExpoNotSignedInError` and `ExpoInvalidCredentialError`'s messages.
pub(super) const NOT_SIGNED_IN: &str = "No Expo credential on the server: save an access token for this host, set EXPO_TOKEN, or run `eas login`.";

fn invalid_credential(source: &str) -> String {
    let name = match source {
        "settings" => "The access token saved for this host",
        "env" => "EXPO_TOKEN",
        _ => "The eas login session",
    };
    format!("{name} is not a usable Expo credential. Replace it.")
}

fn credential(
    source: &'static str,
    header: &'static str,
    value: &str,
) -> Result<Credential, String> {
    if value.is_empty() || !value.bytes().all(|b| (0x21..=0x7e).contains(&b)) {
        return Err(invalid_credential(source));
    }
    Ok(Credential {
        source,
        header,
        value: if header == "authorization" {
            format!("Bearer {value}")
        } else {
            value.to_owned()
        },
    })
}

/// `resolveExpoCredential`: a token saved for the host, then `EXPO_TOKEN`,
/// then the `eas login` session in `~/.expo/state.json`.
pub(super) fn resolve_credential(
    saved: &str,
    home: &std::path::Path,
) -> Result<Credential, String> {
    let saved = saved.trim();
    if !saved.is_empty() {
        return credential("settings", "authorization", saved);
    }
    if let Some(token) = std::env::var("EXPO_TOKEN")
        .ok()
        .map(|t| t.trim().to_owned())
        .filter(|t| !t.is_empty())
    {
        return credential("env", "authorization", &token);
    }
    let secret = std::fs::read_to_string(home.join(".expo").join("state.json"))
        .ok()
        .and_then(|text| serde_json::from_str::<Value>(&text).ok())
        .and_then(|state| {
            state["auth"]["sessionSecret"]
                .as_str()
                .map(|s| s.trim().to_owned())
        })
        .filter(|s| !s.is_empty())
        .ok_or_else(|| NOT_SIGNED_IN.to_owned())?;
    credential("eas-login", "expo-session", &secret)
}

/// `ExpoApiError`.
#[derive(Clone, Debug)]
pub(super) struct ApiError {
    pub operation: &'static str,
    pub detail: Option<String>,
    /// Expo answered and refused, so a mutation did nothing.
    pub rejected: bool,
    pub status: Option<u16>,
}

impl ApiError {
    pub fn message(&self) -> String {
        match &self.detail {
            Some(detail) => format!("Expo could not {}: {detail}", self.operation),
            None => format!("Expo could not {}.", self.operation),
        }
    }
}

/// `toExpoApiError`: Expo's answer as the reference describes it, the
/// credential cut out of anything Expo said.
fn api_error(
    operation: &'static str,
    credential: &Credential,
    status: Option<u16>,
    answer: Option<&Value>,
    transport: bool,
) -> ApiError {
    let errors: Vec<&Value> = answer
        .and_then(|body| body["errors"].as_array())
        .map(|errors| errors.iter().collect())
        .unwrap_or_default();
    let response_error = answer.is_some() && !transport;
    let fault = errors.iter().any(|error| {
        let extensions = &error["extensions"];
        extensions["isTransient"] == true
            || (extensions["errorType"].is_string() && extensions["errorType"] != "USER")
            || extensions["errorCode"] == "INTERNAL_SERVER_ERROR"
    });
    let users_fault = !errors.is_empty()
        && errors
            .iter()
            .all(|error| error["extensions"]["errorType"] == "USER");
    let data = answer.and_then(|body| body.get("data"));
    let uncertain = response_error
        && (fault || (data.is_some() && !(data == Some(&Value::Null) && users_fault)));
    let rejected = status
        .is_some_and(|status| status < 500 && !uncertain && (status >= 400 || response_error));
    let secret = credential.value.clone();
    let token = secret.strip_prefix("Bearer ").unwrap_or(&secret).to_owned();
    let scrub = |text: String| -> String {
        text.replace(&secret, "[redacted]")
            .replace(&token, "[redacted]")
            .chars()
            .take(300)
            .collect()
    };
    let detail = if matches!(status, Some(401 | 403)) {
        let what = if credential.source == "eas-login" {
            "eas login session"
        } else {
            "access token"
        };
        format!("the {what} was rejected (HTTP {})", status.unwrap())
    } else if response_error {
        errors
            .iter()
            .map(|error| error["message"].as_str().unwrap_or_default().to_owned())
            .collect::<Vec<_>>()
            .join("; ")
    } else if transport {
        match status {
            None => "Expo's API is unreachable".to_owned(),
            Some(status) => format!("unexpected response (HTTP {status})"),
        }
    } else {
        "unexpected response".to_owned()
    };
    ApiError {
        operation,
        detail: Some(scrub(detail)),
        rejected,
        status,
    }
}

/// One GraphQL operation with the credential: its `data`, or how it failed.
pub(super) async fn call(
    credential: &Credential,
    operation: &'static str,
    name: &str,
    variables: Option<Value>,
) -> Result<Value, ApiError> {
    let document = &DOCUMENTS[name];
    // An operation without variables still sends `{}`, as the reference's client encodes it.
    let body = json!({
        "query": document["query"],
        "operationName": name,
        "variables": variables.unwrap_or_else(|| json!({})),
    });
    let request = client()
        .post(EXPO_GRAPHQL_URL)
        .header(credential.header, &credential.value)
        .header(
            "accept",
            "application/graphql-response+json, application/json",
        )
        .json(&body);
    let timeout = || ApiError {
        operation,
        detail: Some("Expo's API did not answer in time".into()),
        rejected: false,
        status: None,
    };
    let response = match tokio::time::timeout(REQUEST_TIMEOUT, request.send()).await {
        Err(_) => return Err(timeout()),
        Ok(Err(_)) => return Err(api_error(operation, credential, None, None, true)),
        Ok(Ok(response)) => response,
    };
    let status = response.status().as_u16();
    let content_type = response
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or_default()
        .to_ascii_lowercase();
    let body: Option<Value> = match tokio::time::timeout(REQUEST_TIMEOUT, response.bytes()).await {
        Err(_) => return Err(timeout()),
        Ok(bytes) => bytes
            .ok()
            .and_then(|bytes| serde_json::from_slice(&bytes).ok()),
    };
    let graphql_body = body.as_ref().filter(|body| {
        body.is_object()
            && (body.get("data").is_some() || body.get("errors").is_some())
            && body.get("errors").is_none_or(Value::is_array)
            && body
                .get("data")
                .is_none_or(|data| data.is_null() || data.is_object())
    });
    let is_json = content_type.contains("application/graphql-response+json")
        || content_type.contains("application/json");
    match graphql_body {
        Some(body) if is_json => {
            let has_errors = body["errors"].as_array().is_some_and(|e| !e.is_empty());
            if has_errors || body["data"].is_null() {
                return Err(api_error(
                    operation,
                    credential,
                    Some(status),
                    Some(body),
                    false,
                ));
            }
            if !(200..300).contains(&status) {
                return Err(api_error(operation, credential, Some(status), None, true));
            }
            Ok(body["data"].clone())
        }
        _ => Err(api_error(operation, credential, Some(status), None, true)),
    }
}

/// `viewer`: who the credential signs in as, and their apps.
pub(super) async fn viewer(credential: &Credential) -> Result<(String, Vec<Value>), ApiError> {
    const OPERATION: &str = "read the signed-in account";
    let data = call(credential, OPERATION, "T3ExpoViewer", None).await?;
    let actor = &data["meActor"];
    if actor.is_null() {
        return Err(ApiError {
            operation: OPERATION,
            detail: Some("no account is signed in".into()),
            rejected: false,
            status: None,
        });
    }
    let name = actor["username"]
        .as_str()
        .map(str::to_owned)
        .or_else(|| {
            actor.get("firstName").map(|first| {
                first
                    .as_str()
                    .unwrap_or(actor["__typename"].as_str().unwrap_or_default())
                    .to_owned()
            })
        })
        .unwrap_or_else(|| actor["__typename"].as_str().unwrap_or_default().to_owned());
    let apps = actor["accounts"]
        .as_array()
        .into_iter()
        .flatten()
        .flat_map(|account| {
            account["appsPaginated"]["edges"]
                .as_array()
                .cloned()
                .unwrap_or_default()
        })
        .map(|edge| json!({"id": edge["node"]["id"], "fullName": edge["node"]["fullName"]}))
        .collect();
    Ok((name, apps))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn describes_failures_as_the_reference_does() {
        let credential = Credential {
            source: "settings",
            header: "authorization",
            value: "Bearer secret-token".into(),
        };
        let rejected = api_error(
            "read the signed-in account",
            &credential,
            Some(401),
            None,
            true,
        );
        assert_eq!(
            rejected.message(),
            "Expo could not read the signed-in account: the access token was rejected (HTTP 401)"
        );
        assert!(rejected.rejected);
        let answer = json!({"data": null, "errors": [{"message": "No app secret-token", "extensions": {"errorType": "USER"}}]});
        let user = api_error(
            "start a simulator session",
            &credential,
            Some(200),
            Some(&answer),
            false,
        );
        assert_eq!(
            user.message(),
            "Expo could not start a simulator session: No app [redacted]"
        );
        assert!(user.rejected);
        let unreachable = api_error("list simulator sessions", &credential, None, None, true);
        assert_eq!(
            unreachable.message(),
            "Expo could not list simulator sessions: Expo's API is unreachable"
        );
        assert!(!unreachable.rejected);
        assert_eq!(
            credential_error("settings", "two words"),
            "The access token saved for this host is not a usable Expo credential. Replace it."
        );
    }

    fn credential_error(source: &'static str, value: &str) -> String {
        credential(source, "authorization", value).unwrap_err()
    }
}
